Here is the commit message:
dog: fix check of snapshot vdi

This fixes a bug introduced by the commit 996751b.

Signed-off-by: MORITA Kazutaka <morita.kazutaka@lab.ntt.co.jp>
Signed-off-by: Liu Yuan <namei.unix@gmail.com>

Here is the root cause:
The bug was caused by using the incorrect variable `inode->vdi_id` instead of the correct variable `vid` when calling the `vid_to_data_oid` function. This likely led to incorrect object identifiers being generated, which would disrupt the functionality of the snapshot VDI check.

Here is the patch:

 int do_vdi_check(const struct sd_inode *inode)
 {
 	int max_idx;
 	uint64_t done = 0, oid;
 	uint32_t vid;
 	struct work_queue *wq;

 	if (sd_nodes_nr < inode->nr_copies) {
 		sd_err("ABORT: Not enough active nodes for consistency-check");
 		return EXIT_FAILURE;
 	}

 	wq = create_work_queue("vdi check", WQ_DYNAMIC);

 	queue_vdi_check_work(inode, vid_to_vdi_oid(inode->vdi_id), NULL, wq);

 	max_idx = DIV_ROUND_UP(inode->vdi_size, SD_DATA_OBJ_SIZE);
 	vdi_show_progress(done, inode->vdi_size);
 	for (int idx = 0; idx < max_idx; idx++) {
 		vid = inode->data_vdi_id[idx];
 		if (vid) {
-			oid = vid_to_data_oid(inode->vdi_id, idx);
+			oid = vid_to_data_oid(vid, idx);
 			queue_vdi_check_work(inode, oid, &done, wq);
 		} else {
 			done += SD_DATA_OBJ_SIZE;
 			vdi_show_progress(done, inode->vdi_size);
 		}
 	}

 	work_queue_wait(wq);

 	fprintf(stdout, "finish check&repair %s\n", inode->name);

 	return EXIT_SUCCESS;
 }



